import {getContentMode} from "@/lib/knowledge-admin/mode";
import {ManagedLearnPage} from "@/features/study/managed-pages";
import {readExperienceMode} from "@/lib/study/mode";
import {StudyLearnPage,StudyUnavailable} from "@/features/study/pages";
import {UiText} from "@/lib/i18n/ui-text";
import {UiNav} from "@/components/ui-nav";
import {uiMessage,uiValue} from "@/lib/i18n/format";
import {getUiMetadata} from "@/lib/i18n/server";
import {UiPageTitle} from "@/components/ui-page-title";
export async function generateMetadata(){return getUiMetadata("page.learn");}
import Link from "next/link";
import {getLearningClient} from "@/lib/learning/server-client";
import {learningActor,learningPageQuery} from "@/features/learning/page-data";
import {LearningBoundary,LearningNotice} from "@/features/learning/learning-status";
import {OverviewPanel} from "@/features/learning/overview-panel";
import {PathProgress} from "@/features/learning/path-progress";
import {KnowledgeList} from "@/features/learning/knowledge-list";
export const dynamic="force-dynamic";
async function LegacyLearnPage({searchParams}:{searchParams:Promise<Record<string,string|string[]|undefined>>}){const query=learningPageQuery(await searchParams,"learn");if(!query)return <><UiPageTitle messageKey="page.learn"/>{<section className="content-state" role="alert"><h1><UiText notice={uiMessage("page.invalid.learning.parameters.29cb84",{})}/></h1><Link prefetch={false} href="/learn"><UiText notice={uiMessage("page.reset.learning.view.061672",{})}/></Link></section>}</>;const actor=await learningActor();if(!actor.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={actor.error}/>}</>;const client=getLearningClient();let body:React.ReactNode;if(query.enrollment){const route=await client.readLearningPath(query.enrollment);if(!route.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={route}/>}</>;const nodes=await client.listLearningPathNodes(query.enrollment,{limit:20,offset:query.offset});if(!nodes.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={nodes}/>}</>;body=<><PathProgress path={route.data.summary} nodes={nodes.data.items}/><UiNav label={uiMessage("learning.page.routePages",{})}>{query.offset>0&&<Link prefetch={false} href={`/learn?enrollment=${query.enrollment}&offset=${Math.max(0,query.offset-20)}`}><UiText notice={uiMessage("page.previous.nodes.44fb9e",{})}/></Link>}{query.offset+20<nodes.data.total&&<Link prefetch={false} href={`/learn?enrollment=${query.enrollment}&offset=${query.offset+20}`}><UiText notice={uiMessage("page.next.nodes.dbf84b",{})}/></Link>}</UiNav><Link prefetch={false} href="/learn"><UiText notice={uiMessage("page.back.to.my.learning.e67643",{})}/></Link></>}else{const overview=await client.readLearningOverview();if(!overview.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={overview}/>}</>;const paths=await client.listLearningPaths({limit:20,offset:query.pathOffset});if(!paths.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={paths}/>}</>;const knowledge=await client.listLearningKnowledge({limit:20,offset:query.knowledgeOffset});if(!knowledge.ok)return <><UiPageTitle messageKey="page.learn"/>{<LearningNotice result={knowledge}/>}</>;body=<><OverviewPanel overview={overview.data}/><section className="panel"><h2><UiText notice={uiMessage("page.your.saved.routes.57bbd0",{})}/></h2>{paths.data.items.length?paths.data.items.map(p=><p key={p.id}><Link prefetch={false} href={"/learn?enrollment="+p.id}><UiText notice={uiMessage("page.value.saved.version.value.04f7f0",{v0:uiValue(p.title),v1:uiValue(p.path.version)})}/></Link></p>):<p><UiText notice={uiMessage("page.choose.a.reviewed.route.then.select.join.route.to.save.your.progr.8cbbe5",{})}/></p>}<UiNav label={uiMessage("learning.page.savedPages",{})}>{query.pathOffset>0&&<Link prefetch={false} href={"/learn?pathOffset="+Math.max(0,query.pathOffset-20)}><UiText notice={uiMessage("page.previous.routes.eb58cc",{})}/></Link>}{query.pathOffset+20<paths.data.total&&<Link prefetch={false} href={"/learn?pathOffset="+(query.pathOffset+20)}><UiText notice={uiMessage("page.next.routes.e5621d",{})}/></Link>}</UiNav></section><KnowledgeList page={knowledge.data}/></>};return <><UiPageTitle messageKey="page.learn"/>{<><header className="page-heading"><p className="eyebrow"><UiText notice={uiMessage("page.one.idea.at.a.time.070016",{})}/></p><h1><UiText notice={uiMessage("page.learn",{})}/></h1><p><UiText notice={uiMessage("page.see.what.you.have.read.assessed.and.unlocked.fe8551",{})}/></p></header><LearningBoundary actorId={actor.id}>{body}</LearningBoundary></>}</>}

export default async function Page(props:{searchParams:Promise<Record<string,string|string[]|undefined>>}){const content=await getContentMode();if(content===null)return <StudyUnavailable/>;if(content.mode==="managed")return <ManagedLearnPage {...props}/>;const mode=await readExperienceMode();if(mode===null)return <StudyUnavailable/>;if(mode==="topics")return <StudyLearnPage {...props}/>;return <LegacyLearnPage {...props}/>;}
